import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"兌","description":"周易集解 - 兌","frontmatter":{"title":"兌","description":"周易集解 - 兌"},"headers":[],"relativePath":"classics/jijie/058.md","filePath":"classics/jijie/058.md"}'),l={name:"classics/jijie/058.md"};function n(d,a,t,s,p,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="兌" tabindex="-1">兌 <a class="header-anchor" href="#兌" aria-label="Permalink to “兌”">​</a></h1><h2 id="兌-1" tabindex="-1">兌 <a class="header-anchor" href="#兌-1" aria-label="Permalink to “兌”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>兌，亨，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：入而後說之，故受之以兌。兌者，說也。</p><p>崔憬曰：巽以申命行事，入於刑者也。入刑而後說之，所謂人忘其勞死也。</p><p>虞翻曰：大壯五之三也。剛中而柔外，二失正，動應五承三，故亨利貞也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：兌，說也。剛中而柔外，說以利貞，是以順乎天而應乎人。說以先民，民忘其勞；說以犯難，民忘其死，說之大民勸矣哉。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：兌口，故說也。</p><p>虞翻曰：剛中謂二五，柔外謂三上也。二、三、四利之正，故說以利貞也。</p><p>虞翻曰：大壯乾為天，謂五也。人謂三矣。二變順五承三，故順乎天應乎人。坤為順也。</p><p>虞翻曰：謂二、四已變成屯。坎為勞，震喜，兌說，坤為民，坎為心，民心喜說，有順比象，故忘其勞也。</p><p>虞翻曰：體屯，故難也。三至上，體大過死。變成屯，民說無疆。故民忘其死。坎心為忘，或以坤為死也。</p><p>虞翻曰：體比順象，故勞而不怨。震為喜笑，故人勸也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：麗澤，兌，君子以朋友講習。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：君子，大壯乾也。陽息見兌，學以聚之，問以辯之。兌二陽同類為朋，伏艮為友，坎為習，震為講，兌兩口對，故朋友講習也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，和兌，吉。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：得位，四變應已，故和兌吉矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：和兌之吉，行未疑也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：四變應初，震為行，坎為疑，故行未疑。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，孚兌，吉，悔亡。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：孚謂五也。四已變，五在坎中，稱孚。二動得位，應之，故｢孚兌，吉，悔亡｣矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：孚兌之吉，信志也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：二變應五，謂四已變，坎為志，故信志也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，來兌，兇。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：從大壯來，失位，故來兌兇矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：來兌之兇，位不當也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>案：以陰居陽，故位不當。諂邪求悅，所以必兇。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，商兌未寧，介疾有喜。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：巽為近利市三倍，故稱商兌。變之坎，水性流。震為行。謂二已變，體比象，故未寧，與比不寧方來同義也。坎為疾，故介疾。得位承五，故有喜。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九四之喜，有慶也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：陽為慶，謂五也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，孚於剝，有厲。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：孚，謂五也。二四變，體剝象故孚於剝。在坎未光，有厲也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：孚於剝，位正當也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>案：以陽居尊位，應二比四，孚剝有厲，位正當也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，引兌。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：無應乘陽。動而之巽，為繩。艮為手。應在三，三未之正。故引兌也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：上六引兌，未光也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：二四已變而體屯，上三未為離，故未光也。</p>',69)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
